=<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex, nofollow">
<title>ShelfWise Admin</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Space+Grotesk:wght@500;600&display=swap">
<style>
:root{--bg:#f6f7f9;--panel:#fff;--fg:#14171c;--muted:#5f6670;--line:#e3e6ea;--accent:#1f6feb;--ok:#1a7f45;--warn:#b26a00;--bad:#c62828;--soft:#eef2f7;--shadow:0 10px 30px rgba(15,23,42,.12);color-scheme:light}
@media (prefers-color-scheme:dark){:root{--bg:#0e1013;--panel:#171a1f;--fg:#eceef1;--muted:#9aa2ad;--line:#2a2f37;--accent:#5b9dff;--ok:#4cc38a;--warn:#e5a33a;--bad:#f06a6a;--soft:#1f242b;--shadow:0 10px 30px rgba(0,0,0,.5);color-scheme:dark}}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.45 Inter,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
.wrap{max-width:1150px;margin:0 auto;padding:24px max(16px,env(safe-area-inset-right,0px)) 48px max(16px,env(safe-area-inset-left,0px));display:flex;flex-direction:column;gap:20px}
h1,h2{font-family:"Space Grotesk",Inter,system-ui,sans-serif;margin:0}
h1{font-size:1.7rem;font-weight:600}
h2{font-size:1.1rem;font-weight:600}
.sub{color:var(--muted);margin:4px 0 0;font-size:.9rem}
.top{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:flex-end;gap:12px}
.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.spread{justify-content:space-between}
.btn{font:inherit;font-weight:600;font-size:.9rem;border-radius:8px;padding:8px 14px;border:1px solid var(--line);background:var(--panel);color:var(--fg);cursor:pointer}
.btn:hover{border-color:var(--muted)}
.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}
.btn.good{color:var(--ok);border-color:var(--ok);background:transparent}
.btn.danger{color:var(--bad);border-color:var(--bad);background:transparent}
.btn.small{padding:5px 10px;font-size:.82rem}
.btn:disabled{opacity:.5;cursor:default}
.btn:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.tabs{display:flex;gap:4px;padding:4px;border:1px solid var(--line);border-radius:10px;background:var(--panel)}
.tab{font:inherit;font-weight:600;border:0;background:transparent;color:var(--muted);padding:7px 16px;border-radius:7px;cursor:pointer}
.tab[aria-selected="true"]{background:var(--soft);color:var(--fg)}
.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
@media (max-width:720px){.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
.kpi{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px;min-width:0}
.kpi .l{font-size:.72rem;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:600}
.kpi .v{font-family:"Space Grotesk",Inter,sans-serif;font-size:2rem;font-weight:600;line-height:1.2;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.kpi .n{font-size:.8rem;color:var(--muted)}
.kpi.warn .v{color:var(--warn)}.kpi.bad .v{color:var(--bad)}.kpi.good .v{color:var(--ok)}
.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:12px;min-width:0}
.scroll{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:.9rem;font-variant-numeric:tabular-nums}
th{text-align:left;font-size:.7rem;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:600;padding:6px 8px;border-bottom:1px solid var(--line);white-space:nowrap}
td{padding:9px 8px;border-bottom:1px solid var(--line);vertical-align:middle}
tr:last-child td{border-bottom:0}
.r{text-align:right}.nw{white-space:nowrap}.muted{color:var(--muted)}.strong{font-weight:600}
td.acts{white-space:nowrap;text-align:right}
td.acts .btn{margin-left:4px}
.empty{color:var(--muted);text-align:center;padding:18px 8px}
.toggle{font:inherit;font-weight:600;background:none;border:0;color:var(--fg);cursor:pointer;padding:0;text-align:left}
.toggle:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
tr.shop td{background:var(--soft)}
tr.user td.indent{padding-left:24px;color:var(--muted);font-weight:500}
.chip{display:inline-block;font-size:.72rem;font-weight:600;padding:1px 8px;border-radius:999px;border:1px solid currentColor;white-space:nowrap}
.chip.ok{color:var(--ok)}.chip.warn{color:var(--warn)}.chip.bad{color:var(--bad)}.chip.mute{color:var(--muted)}
.input,select.input{font:inherit;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--fg);min-width:0}
.search{width:240px;max-width:100%}
.pager{display:flex;flex-wrap:wrap;gap:6px;justify-content:center}
.pager .btn{min-width:36px;padding:5px 9px}
.pager .btn[aria-current="page"]{background:var(--accent);border-color:var(--accent);color:#fff}
.login{max-width:380px;margin:12vh auto 0;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:24px;display:flex;flex-direction:column;gap:14px}
.overlay{position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:flex-end;justify-content:center;padding:16px;z-index:20}
@media (min-width:640px){.overlay{align-items:center}}
.sheet{background:var(--panel);border-radius:14px;box-shadow:var(--shadow);width:100%;max-width:520px;max-height:90vh;overflow:auto;padding:20px;display:flex;flex-direction:column;gap:14px}
.form{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.full{grid-column:1/-1}
.field{display:flex;flex-direction:column;gap:4px;min-width:0}
.field label{font-size:.75rem;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}
.link{font-size:.82rem;word-break:break-all;background:var(--soft);border-radius:8px;padding:10px;user-select:all}
.err{color:var(--bad);font-size:.85rem;min-height:1.2em;margin:0}
.toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--fg);color:var(--bg);padding:10px 16px;border-radius:10px;font-weight:600;z-index:30;max-width:90vw}
</style>
</head>
<body>

<form class="login" id="loginBox" autocomplete="on">
  <h1>ShelfWise Admin</h1>
  <div class="field"><label for="pw">Password</label><input class="input" id="pw" type="password" autocomplete="current-password" required></div>
  <p class="err" id="loginErr" role="alert"></p>
  <button class="btn primary" type="submit" id="loginBtn">Sign In</button>
</form>

<div class="wrap" id="app" hidden>
  <div class="top">
    <div><h1>ShelfWise Admin</h1><p class="sub" id="updated"></p></div>
    <div class="row">
      <div class="tabs" role="tablist" aria-label="Sections">
        <button class="tab" role="tab" id="tab-shops" aria-selected="true" aria-controls="shops">Shops</button>
        <button class="tab" role="tab" id="tab-pay" aria-selected="false" aria-controls="pay">Payments</button>
      </div>
      <button class="btn" type="button" id="refreshBtn">Refresh</button>
      <button class="btn" type="button" id="logoutBtn">Sign Out</button>
    </div>
  </div>

  <section id="shops" role="tabpanel" aria-labelledby="tab-shops" style="display:flex;flex-direction:column;gap:20px">
    <div class="kpis">
      <div class="kpi good"><div class="l">Active Shops</div><div class="v" id="kActive">—</div><div class="n">At least one active user</div></div>
      <div class="kpi"><div class="l">Paused Shops</div><div class="v" id="kPaused">—</div><div class="n">All users set to NO</div></div>
      <div class="kpi"><div class="l">Users</div><div class="v" id="kUsers">—</div><div class="n">Rows in Clients</div></div>
      <div class="kpi warn"><div class="l">No Dashboard Link</div><div class="v" id="kNoLink">—</div><div class="n">Active users with a sheet</div></div>
    </div>
    <div class="card">
      <div class="row spread">
        <h2>Pharmacies</h2>
        <div class="row">
          <input class="input search" id="cSearch" type="search" placeholder="Search shop, phone or note" aria-label="Search clients">
          <button class="btn primary" type="button" id="addClientBtn">+ Add Client</button>
        </div>
      </div>
      <div class="scroll"><table>
        <thead><tr><th>Pharmacy / Role</th><th>Users</th><th>Status</th><th>Alerts</th><th>Phone</th><th>Notes</th><th class="r">Actions</th></tr></thead>
        <tbody id="clientRows"></tbody>
      </table></div>
      <nav class="pager" id="cPager" aria-label="Client pages"></nav>
    </div>
  </section>

  <section id="pay" role="tabpanel" aria-labelledby="tab-pay" hidden style="flex-direction:column;gap:20px">
    <div class="kpis">
      <div class="kpi bad"><div class="l">Overdue</div><div class="v" id="kOverdue">—</div><div class="n" id="kOverdueAmt">&nbsp;</div></div>
      <div class="kpi warn"><div class="l">Due In 7 Days</div><div class="v" id="kDue7">—</div><div class="n" id="kDue7Amt">&nbsp;</div></div>
      <div class="kpi"><div class="l">Expected This Month</div><div class="v" id="kExpected">—</div><div class="n">Due and paid this month</div></div>
      <div class="kpi good"><div class="l">Collected This Month</div><div class="v" id="kCollected">—</div><div class="n">Marked paid this month</div></div>
    </div>
    <div class="card">
      <div class="row spread">
        <h2>Payments</h2>
        <div class="row">
          <input class="input search" id="pSearch" type="search" placeholder="Search shop" aria-label="Search payments">
          <select class="input" id="pFilter" aria-label="Show">
            <option value="open">Due &amp; Overdue</option>
            <option value="paid">Paid</option>
            <option value="all">All</option>
          </select>
          <button class="btn primary" type="button" id="addPayBtn">+ Add Payment</button>
        </div>
      </div>
      <div class="scroll"><table>
        <thead><tr><th>Shop</th><th>Payment Date</th><th class="r">Amount</th><th>Status</th><th>Paid On</th><th>Notes</th><th class="r">Actions</th></tr></thead>
        <tbody id="payRows"></tbody>
      </table></div>
      <nav class="pager" id="pPager" aria-label="Payment pages"></nav>
    </div>
  </section>
</div>

<div class="overlay" id="clientEd" hidden>
  <div class="sheet" role="dialog" aria-modal="true" aria-labelledby="ceTitle">
    <h2 id="ceTitle">Edit Client</h2>
    <div class="form">
      <div class="field full"><label for="cName">Shop Name</label><input class="input" id="cName" maxlength="120"></div>
      <div class="field"><label for="cRole">Role</label><select class="input" id="cRole"><option>Owner</option><option>Manager</option><option>Staff</option></select></div>
      <div class="field"><label for="cPhone">Phone</label><input class="input" id="cPhone" inputmode="tel" maxlength="20"></div>
      <div class="field"><label for="cActive">Status</label><select class="input" id="cActive"><option value="YES">Active</option><option value="NO">Paused</option></select></div>
      <div class="field"><label for="cAlerts">Alerts</label><select class="input" id="cAlerts"><option>ON</option><option>OFF</option></select></div>
      <div class="field"><label for="cChat">Telegram Chat ID</label><input class="input" id="cChat" inputmode="numeric" maxlength="20"></div>
      <div class="field"><label for="cSheet">Stock Sheet ID</label><input class="input" id="cSheet" maxlength="100"></div>
      <div class="field full"><label for="cNotes">Notes</label><input class="input" id="cNotes" maxlength="200"></div>
    </div>
    <p class="err" id="ceErr" role="alert"></p>
    <div class="row spread"><span></span><div class="row"><button class="btn" type="button" id="ceCancel">Cancel</button><button class="btn primary" type="button" id="ceSave">Save</button></div></div>
  </div>
</div>

<div class="overlay" id="linkEd" hidden>
  <div class="sheet" role="dialog" aria-modal="true" aria-labelledby="leTitle">
    <h2 id="leTitle">Dashboard Link</h2>
    <p class="sub" id="leInfo"></p>
    <div class="link" id="leLink"></div>
    <p class="err" id="leErr" role="alert"></p>
    <div class="row spread">
      <button class="btn danger" type="button" id="leRemove">Remove Link</button>
      <div class="row">
        <button class="btn" type="button" id="leCopy">Copy</button>
        <a class="btn" id="leOpen" href="#" target="_blank" rel="noopener">Open</a>
        <button class="btn primary" type="button" id="leNew">New Link</button>
      </div>
    </div>
    <div class="row" style="justify-content:flex-end"><button class="btn" type="button" id="leClose">Close</button></div>
  </div>
</div>

<div class="overlay" id="payEd" hidden>
  <div class="sheet" role="dialog" aria-modal="true" aria-labelledby="peTitle">
    <h2 id="peTitle">Add Payment</h2>
    <div class="form">
      <div class="field full"><label for="pShop">Shop</label><select class="input" id="pShop"></select></div>
      <div class="field"><label for="pDate">Payment Date</label><input class="input" id="pDate" type="date"></div>
      <div class="field"><label for="pAmt">Amount (৳)</label><input class="input" id="pAmt" type="number" min="0" step="1" inputmode="decimal"></div>
      <div class="field full"><label for="pNotes">Notes</label><input class="input" id="pNotes" maxlength="200"></div>
    </div>
    <p class="err" id="peErr" role="alert"></p>
    <div class="row spread">
      <button class="btn danger" type="button" id="peCancelPay">Cancel Payment</button>
      <div class="row"><button class="btn" type="button" id="peClose">Close</button><button class="btn primary" type="button" id="peSave">Save</button></div>
    </div>
  </div>
</div>

<div class="overlay" id="paidEd" hidden>
  <div class="sheet" role="dialog" aria-modal="true" aria-labelledby="pdTitle">
    <h2 id="pdTitle">Mark As Paid</h2>
    <p id="pdInfo"></p>
    <p class="sub">The next payment is added one month later.</p>
    <p class="err" id="pdErr" role="alert"></p>
    <div class="row" style="justify-content:flex-end"><button class="btn" type="button" id="pdClose">Cancel</button><button class="btn good" type="button" id="pdOk">Confirm Paid</button></div>
  </div>
</div>

<div class="toast" id="toast" hidden></div>

<script>
const API = "{{ 'https://' + String($json.headers['x-forwarded-host'] || $json.headers.host || '').replace(/[^A-Za-z0-9.:-]/g, '') + '/webhook/shelfwise-admin-api' }}";
const $ = (id) => document.getElementById(id);
let password = '';
let data = { clients: [], payments: [], today: '' };
let cPage = 1, pPage = 1;
const PER = 10;
try { password = sessionStorage.getItem('sw_admin') || ''; } catch (e) {}

const taka = (n) => '৳' + Number(n || 0).toLocaleString('en-IN');
const todayStr = () => data.today || new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Dhaka' });
const daysBetween = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const toast = (m) => { const t = $('toast'); t.textContent = m; t.hidden = false; clearTimeout(toast._t); toast._t = setTimeout(() => { t.hidden = true; }, 3000); };
const td = (v, cls) => { const c = document.createElement('td'); if (cls) c.className = cls; c.textContent = v === null || v === undefined || v === '' ? '—' : String(v); return c; };
const chipTd = (text, tone) => { const c = document.createElement('td'); const s = document.createElement('span'); s.className = 'chip ' + tone; s.textContent = text; c.append(s); return c; };
const btn = (label, cls, fn, aria) => { const b = document.createElement('button'); b.type = 'button'; b.className = 'btn small ' + (cls || ''); b.textContent = label; if (aria) b.setAttribute('aria-label', aria); b.addEventListener('click', fn); return b; };
const empty = (tbody, cols, text) => { const tr = document.createElement('tr'); const c = td(text, 'empty'); c.colSpan = cols; tr.append(c); tbody.replaceChildren(tr); };

async function call(action, payload) {
  const body = new URLSearchParams({ payload: JSON.stringify({ password, action, data: payload || {} }) });
  const r = await fetch(API, { method: 'POST', body });
  let j = null; try { j = await r.json(); } catch (e) {}
  if (!r.ok || !j) throw new Error('Couldn\'t reach the server. Try again.');
  if (!j.ok) { const e = new Error(j.error || 'Something went wrong.'); e.auth = /password/i.test(j.error || ''); throw e; }
  return j;
}

async function load(quiet) {
  try {
    const j = await call('load');
    data = { clients: j.clients || [], payments: j.payments || [], today: j.today };
    $('loginBox').hidden = true; $('app').hidden = false;
    $('updated').textContent = 'Updated ' + new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) + ' · Admin Panel (ShelfWise)';
    renderAll();
  } catch (e) {
    if (e.auth) { signOut(e.message); return; }
    if (!quiet) toast(e.message);
  }
}
function signOut(msg) {
  password = ''; try { sessionStorage.removeItem('sw_admin'); } catch (e) {}
  $('app').hidden = true; $('loginBox').hidden = false; $('loginErr').textContent = msg || ''; $('pw').value = ''; $('pw').focus();
}

function shopStats() {
  const shops = new Map();
  data.clients.forEach((c) => { const s = shops.get(c.ClientName) || { active: false }; if (c.Active === 'YES') s.active = true; shops.set(c.ClientName, s); });
  return [...shops.values()];
}
const payStatus = (p) => {
  if (p.Status === 'Paid') return { label: 'Paid', tone: 'ok', rank: 4 };
  if (p.Status === 'Cancelled') return { label: 'Cancelled', tone: 'mute', rank: 5 };
  const d = /^\d{4}-\d{2}-\d{2}$/.test(p.PaymentDate) ? daysBetween(p.PaymentDate, todayStr()) : null;
  if (d === null) return { label: 'No Date', tone: 'mute', rank: 3 };
  if (d < 0) return { label: 'Overdue ' + (-d) + 'd', tone: 'bad', rank: 0, days: d };
  if (d === 0) return { label: 'Due Today', tone: 'warn', rank: 1, days: d };
  if (d <= 7) return { label: 'Due In ' + d + 'd', tone: 'warn', rank: 1, days: d };
  return { label: 'Due', tone: 'mute', rank: 2, days: d };
};

function renderAll() { renderShops(); renderPayments(); }

const openShops = new Set();
function renderShops() {
  const st = shopStats();
  $('kActive').textContent = st.filter((s) => s.active).length;
  $('kPaused').textContent = st.filter((s) => !s.active).length;
  $('kUsers').textContent = data.clients.length;
  $('kNoLink').textContent = data.clients.filter((c) => c.Active === 'YES' && c.SheetID && !c.Link).length;
  const q = $('cSearch').value.trim().toLowerCase();
  const groups = new Map();
  data.clients.forEach((c) => { if (!groups.has(c.ClientName)) groups.set(c.ClientName, []); groups.get(c.ClientName).push(c); });
  const ROLE = { Owner: 0, Manager: 1, Staff: 2 };
  let shops = [...groups.entries()].map(([name, users]) => ({ name, users: users.sort((a, b) => (ROLE[a.Role] ?? 9) - (ROLE[b.Role] ?? 9)) }))
    .sort((a, b) => a.name.localeCompare(b.name));
  if (q) shops = shops.filter((s) => s.name.toLowerCase().includes(q) || s.users.some((u) => [u.Phone, u.Notes, u.Role].join(' ').toLowerCase().includes(q)));
  const pages = Math.max(1, Math.ceil(shops.length / PER)); if (cPage > pages) cPage = pages;
  pager('cPager', pages, cPage, (n) => { cPage = n; renderShops(); });
  if (!shops.length) return empty($('clientRows'), 7, q ? 'No pharmacies match.' : 'No clients yet. Tap + Add Client.');
  const rows = [];
  shops.slice((cPage - 1) * PER, cPage * PER).forEach((s) => {
    const open = openShops.has(s.name) || !!q;
    const active = s.users.some((u) => u.Active === 'YES');
    const tr = document.createElement('tr'); tr.className = 'shop';
    const nameTd = document.createElement('td');
    const tg = document.createElement('button'); tg.type = 'button'; tg.className = 'toggle';
    tg.setAttribute('aria-expanded', open ? 'true' : 'false');
    tg.textContent = (open ? '▾ ' : '▸ ') + s.name;
    tg.addEventListener('click', () => { if (openShops.has(s.name)) openShops.delete(s.name); else openShops.add(s.name); renderShops(); });
    nameTd.append(tg);
    const roles = s.users.map((u) => u.Role || 'User');
    const summary = Object.entries(roles.reduce((m, r) => { m[r] = (m[r] || 0) + 1; return m; }, {})).map(([r, n]) => n + ' ' + r + (n > 1 ? 's' : '')).join(', ');
    tr.append(nameTd, td(summary, 'muted'), chipTd(active ? 'Active' : 'Paused', active ? 'ok' : 'mute'), document.createElement('td'), document.createElement('td'), document.createElement('td'));
    const a = document.createElement('td'); a.className = 'acts';
    a.append(btn('+ User', '', () => openClient(null, s.name), 'Add user to ' + s.name));
    tr.append(a); rows.push(tr);
    if (open) s.users.forEach((c) => {
      const u = document.createElement('tr'); u.className = 'user';
      u.append(td('↳ ' + (c.Role || 'User'), 'indent'), td(c.Link ? 'Has link' : (c.SheetID ? 'No link' : 'No sheet'), 'muted nw'),
        chipTd(c.Active === 'YES' ? 'Active' : 'Paused', c.Active === 'YES' ? 'ok' : 'mute'), td(c.Alerts, 'muted'), td(c.Phone, 'nw'), td(c.Notes, 'muted'));
      const ua = document.createElement('td'); ua.className = 'acts';
      ua.append(btn(c.Link ? 'Link' : 'Make Link', c.Link ? '' : 'good', () => openLink(c), 'Dashboard link for ' + c.ClientName + ' ' + c.Role), btn('Edit', '', () => openClient(c), 'Edit ' + c.ClientName + ' ' + c.Role));
      u.append(ua); rows.push(u);
    });
  });
  $('clientRows').replaceChildren(...rows);
}

function renderPayments() {
  const today = todayStr(); const month = today.slice(0, 7);
  const open = data.payments.filter((p) => p.Status !== 'Paid' && p.Status !== 'Cancelled');
  const overdue = open.filter((p) => payStatus(p).rank === 0);
  const due7 = open.filter((p) => payStatus(p).rank === 1);
  $('kOverdue').textContent = overdue.length; $('kOverdueAmt').textContent = taka(overdue.reduce((s, p) => s + (p.Amount || 0), 0));
